package com.textbook.collections;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class CollisionVulnerabilityDemo {

    // A custom key with a deliberately broken hashCode to force extreme collisions
    static final class BadHashKey implements Comparable<BadHashKey> {
        private final String id;

        BadHashKey(String id) {
            this.id = id;
        }

        @Override
        public int hashCode() {
            // Intentional collision: all instances map to bucket index 1
            return 42;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof BadHashKey)) return false;
            BadHashKey that = (BadHashKey) o;
            return id.equals(that.id);
        }

        @Override
        public int compareTo(BadHashKey other) {
            return this.id.compareTo(other.id);
        }
    }

    public static void main(String[] args) {
        Map<BadHashKey, String> map = new HashMap<>();

        // Inserting 20 items with identical hash codes forces treeification
        for (int i = 0; i < 20; i++) {
            map.put(new BadHashKey("key-" + i), "value-" + i);
        }

        // Lookups will traverse the Red-Black Tree instead of a linear linked list
        System.out.println("Value retrieved: " + map.get(new BadHashKey("key-15")));
    }
}
